int dp[20][ST];        // memo for non-tight states
long long solve(int pos, int state, bool tight) {
    if (pos == len) return accept(state);
    if (!tight && dp[pos][state] != -1) return dp[pos][state];
    int hi = tight ? digits[pos] : 9;
    long long res = 0;
    for (int d = 0; d <= hi; ++d)
        res += solve(pos + 1, next(state, d), tight && d == hi);
    if (!tight) dp[pos][state] = res;
    return res;
}

def count(digits, accept, nxt):
    # digits: most-significant-first list. accept(state)->0/1. nxt(state,d)->state.
    L = len(digits)
    memo = {}
    def solve(pos, state, tight):
        if pos == L:
            return accept(state)
        if not tight and (pos, state) in memo:
            return memo[(pos, state)]
        hi = digits[pos] if tight else 9
        res = 0
        for d in range(hi + 1):
            res += solve(pos + 1, nxt(state, d), tight and d == hi)
        if not tight:
            memo[(pos, state)] = res
        return res
    return solve(0, 0, True)
